const D = { energy:.6, blur:.62, spread:.42, haze:.45, density:.5, speed:1, scale:1, alpha:.85, hue:205, x:.5, y:.56, axis:'horizontal', style:'miniature', act:'wander', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp=(v,a,b)=>Math.max(a,Math.min(b,v));
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
const hsb2rgb=(h,s,v)=>{h=((h%360)+360)%360;s/=100;v/=100;const c=v*s,x=c*(1-Math.abs((h/60)%2-1)),m=v-c;let r,g,b;const sg=Math.floor(h/60)%6;if(sg===0){r=c;g=x;b=0;}else if(sg===1){r=x;g=c;b=0;}else if(sg===2){r=0;g=c;b=x;}else if(sg===3){r=0;g=x;b=c;}else if(sg===4){r=x;g=0;b=c;}else{r=c;g=0;b=x;}return [((r+m)*255)|0,((g+m)*255)|0,((b+m)*255)|0];};
const rgba=(c,a)=>`rgba(${c[0]},${c[1]},${c[2]},${clp(a,0,1).toFixed(4)})`;
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const W=width,H=height,u=Math.min(W,H),t=K.t,key=W+'x'+H,dc=drawingContext;

// ---- size-keyed defocus buffers. Downsample IS the blur (no full-canvas filter()).
if(!S.mid||S.key!==key){
  const mk=n=>{ let w,h; if(W>=H){ w=n; h=Math.max(8,Math.round(n*H/W)); } else { h=n; w=Math.max(8,Math.round(n*W/H)); }
                const q=createGraphics(w,h); q.pixelDensity(1); return q; };
  if(S.mid&&S.mid.remove)S.mid.remove();
  if(S.lo&&S.lo.remove)S.lo.remove();
  S.mid=mk(128); S.lo=mk(42);
  S.midEl=S.mid.elt||S.mid.canvas; S.loEl=S.lo.elt||S.lo.canvas;
  S.key=key;
}
const mid=S.mid, lo=S.lo;

const en=clp(P.energy,0,1);
const sp=0.45+clp(P.speed,.15,4)*0.55;
const style=P.style, vert=(P.axis==='vertical');
const hue=((P.hue%360)+360)%360, alpha=clp(P.alpha,0,1);

// ---- capture the composited frame, then defocus it by successive downsampling
mid.clear(); mid.drawingContext.drawImage(dc.canvas,0,0,mid.width,mid.height);
lo.clear();  lo.drawingContext.drawImage(S.midEl,0,0,lo.width,lo.height);

// ---- the focus plane wanders on four incommensurate real-time rates (never re-phases at 8s)
let amp=0.20, wob=1;
if(P.act==='rack'){ amp=0.34; }
else if(P.act==='breathe'){ amp=0.13; wob=2.1; }
const anchor = vert?P.x:P.y;
const fc = clp(anchor + amp*Math.sin(t*0.077*sp) + 0.09*Math.sin(t*0.19*sp+2.1)
               + 0.05*Math.sin(t*0.041*sp+0.7) + 0.03*Math.sin(t*0.29*sp+1.9), 0.04, 0.96);
const spread=clp(P.spread,0,1);
const fw = clp((0.05+spread*0.30)*(1 + 0.30*wob*Math.sin(t*0.113*sp+1.3) + 0.16*K.swell + 0.10*A.rms), 0.02, 0.55);
const feather = 0.10+spread*0.22;
const blurFloor = style==='dream'?0.34:0;
const bAt = v => clp(blurFloor + clp((Math.abs(v-fc)-fw)/feather,0,1)*clp(P.blur,0,1), 0, 1);

// ---- cross-fade sharp -> defocused in strips along the tilt axis
if(style!=='depth'){
  const N=34, axLen=vert?W:H;
  for(let k=0;k<N;k++){
    const v0=k/N, v1=(k+1)/N, b=bAt((v0+v1)*0.5);
    if(b<=0.015) continue;
    const am=clp(b*1.85,0,1), al=clp((b-0.42)*2.0,0,1);
    const d0=Math.floor(v0*axLen), dl=Math.ceil(v1*axLen)-d0+1;
    if(vert){
      if(am>0.01){ dc.globalAlpha=am*alpha; dc.drawImage(S.midEl, v0*mid.width,0,(v1-v0)*mid.width,mid.height, d0,0,dl,H); }
      if(al>0.01){ dc.globalAlpha=al*alpha; dc.drawImage(S.loEl,  v0*lo.width, 0,(v1-v0)*lo.width, lo.height,  d0,0,dl,H); }
    } else {
      if(am>0.01){ dc.globalAlpha=am*alpha; dc.drawImage(S.midEl, 0,v0*mid.height,mid.width,(v1-v0)*mid.height, 0,d0,W,dl); }
      if(al>0.01){ dc.globalAlpha=al*alpha; dc.drawImage(S.loEl,  0,v0*lo.height, lo.width, (v1-v0)*lo.height,  0,d0,W,dl); }
    }
  }
  dc.globalAlpha=1;
}

// ---- the depth grade: aerial haze far, warm cast near. Drawn, not derived —
// this is what carries the piece over a scene with no highlights in it at all.
const hb = 1 + 0.30*Math.sin(t*0.089*sp+0.4) + 0.16*Math.sin(t*0.211*sp+2.7);
const hz = clp(clp(P.haze,0,1)*(0.45+0.75*en)*hb, 0, 1.6);
const hzB = clp((0.21+0.79*clp(P.haze,0,1))*(0.45+0.75*en)*hb, 0, 1.6);
let s1=clp(fc-fw-feather,0,1), s2=clp(fc-fw,0,1), s3=clp(fc+fw,0,1), s4=clp(fc+fw+feather,0,1);
s2=Math.max(s1,s2); s3=Math.max(s2,s3); s4=Math.max(s3,s4);
const gx1=vert?W:0, gy1=vert?0:H;
if(style==='depth'){
  // abstract: the frame is re-read as a false-colour depth chart
  const g2=dc.createLinearGradient(0,0,gx1,gy1);
  for(let s=0;s<=12;s++){
    const v=s/12, b=bAt(v);
    g2.addColorStop(v, rgba(hsb2rgb(hue+210-170*b, 62+28*b, 10+86*b), alpha*(0.42+0.28*en)));
  }
  dc.fillStyle=g2; dc.fillRect(0,0,W,H);
} else {
  let far, near, fA, nA;
  if(style==='cine'){      far=hsb2rgb(hue,18,64);      near=hsb2rgb(hue+8,22,10);    fA=hz*0.20; nA=hz*0.24; }
  else if(style==='dream'){ far=hsb2rgb(hue+34,20,98);   near=hsb2rgb(hue-26,30,88);   fA=hz*0.40; nA=hz*0.26; }
  else {                    far=hsb2rgb(hue,34,84);      near=hsb2rgb(hue-170,58,9);   fA=hz*0.34; nA=hz*0.44; }
  const g=dc.createLinearGradient(0,0,gx1,gy1);
  g.addColorStop(0,  rgba(far,fA*alpha));
  g.addColorStop(s1, rgba(far,fA*alpha));
  g.addColorStop(s2, rgba(far,0));
  g.addColorStop(s3, rgba(near,0));
  g.addColorStop(s4, rgba(near,nA*alpha));
  g.addColorStop(1,  rgba(near,nA*alpha));
  dc.fillStyle=g; dc.fillRect(0,0,W,H);
}

// ---- patchy atmosphere: soft cells of haze drifting through the defocused zones.
// Sinusoidal drift of the focus plane CANCELS over some 8s windows; these cells
// translate continuously and wrap, so the motion floor holds in every window.
{
  const nh=4+Math.round(clp(P.density,0,1)*4);
  const hc = style==='miniature' ? hsb2rgb(hue,30,88)
           : style==='cine'      ? hsb2rgb(hue,20,72)
           : style==='depth'     ? hsb2rgb(hue+150,44,80)
                                 : hsb2rgb(hue+34,18,100);
  dc.globalCompositeOperation='lighter';
  for(let i=0;i<nh;i++){
    const rr=u*(0.26+0.26*fr(i*3.1+1))*Math.max(0.4,P.scale);
    const dir=fr(i*11)<0.5?-1:1;
    const vx=(0.029+0.031*fr(i*7+2))*dir*sp;
    const bx=(((fr(i*5+2)+t*vx)%1+1)%1)*(W+2*rr)-rr;
    const by=H*(0.10+0.80*fr(i*9+3)) + Math.sin(t*(0.037+0.033*fr(i*13+4))*sp+i*1.7)*u*0.13;
    const vv=clp(vert?bx/W:by/H,0,1);
    const ha=clp(hzB*(0.24+0.58*bAt(vv))*(0.46+0.40*fr(i*17+5))*alpha,0,0.34);
    if(ha<0.004) continue;
    const rg=dc.createRadialGradient(bx,by,0,bx,by,rr);
    rg.addColorStop(0,rgba(hc,ha));
    rg.addColorStop(0.55,rgba(hc,ha*0.42));
    rg.addColorStop(1,rgba(hc,0));
    dc.fillStyle=rg; dc.fillRect(bx-rr,by-rr,rr*2,rr*2);
  }
}

// ---- true-colour bokeh: defocused highlights bloom into discs with a defined rim
if(P.density>0.02 && style!=='depth' && en>0.02){
  lo.loadPixels();
  const lp=lo.pixels, lw=lo.width, lh=lo.height, nMax=Math.round(3+clp(P.density,0,1)*25), thr=0.5;
  const step=Math.max(1,Math.floor((lw*lh)/(nMax*8))), jit=fr(5)*97;
  let drawn=0;
  dc.globalCompositeOperation='lighter';
  for(let idx=(jit|0)%step; idx<lw*lh && drawn<nMax; idx+=step){
    const o=idx*4, br=Math.max(lp[o],lp[o+1],lp[o+2])/255;
    if(br<thr) continue;
    const ix=idx%lw, iy=(idx/lw)|0, v=vert?(ix+0.5)/lw:(iy+0.5)/lh, b=bAt(v);
    if(b<0.12) continue;
    const cx=(ix+0.5)/lw*W + Math.sin(t*0.31+idx*0.7)*u*0.003;
    const cy=(iy+0.5)/lh*H + Math.cos(t*0.27+idx*1.1)*u*0.003;
    const r=u*(0.010+0.05*b)*Math.max(0.3,P.scale)*(1+0.10*K.swell);
    const a=clp((br-thr)*1.7,0,1)*b*(0.25+0.75*en)*0.30*alpha;
    dc.fillStyle=`rgba(${lp[o]},${lp[o+1]},${lp[o+2]},${a.toFixed(4)})`;
    dc.beginPath(); dc.arc(cx,cy,r,0,6.283185); dc.fill();
    dc.strokeStyle=`rgba(${lp[o]},${lp[o+1]},${lp[o+2]},${(a*0.85).toFixed(4)})`;
    dc.lineWidth=Math.max(0.6,r*0.16); dc.stroke();
    drawn++;
  }
}

dc.globalAlpha=1; dc.globalCompositeOperation='source-over';
blendMode(BLEND); dc.shadowBlur=0; noStroke();
